@startuml
class Student {
  +id: String
  +name: String
  +age: Integer
  +gpa: Number
  +enrolled: Boolean
  +birthDate: Date
}
class StudentService {
  +list(): Student
  +create(name: String, age: Integer, gpa: Number, enrolled: Boolean, birthDate: Date): Student
  +update(id: String): Student
  +remove(id: String): void
}
class StudentRepository {
  +list(): Student
  +findById(id: String): Student
  +create(value: Student): Student
  +update(id: String): Student
  +remove(id: String): void
}
StudentService --> StudentRepository : uses
StudentRepository --> Student : persists
@enduml
